import { makeVar } from '@apollo/client';

// Create reactive variable
export const isLoggedInVar = makeVar(false);
export const currentUserVar = makeVar<User | null>(null);

// Use in component
function UserStatus() {
  const isLoggedIn = useReactiveVar(isLoggedInVar);
  const user = useReactiveVar(currentUserVar);

  return (
    <div>
      {isLoggedIn ? `Hello, ${user?.name}` : 'Please log in'}
    </div>
  );
}

// Update anywhere
isLoggedInVar(true);
currentUserVar({ id: '1', name: 'Alice' });

const GET_USER = gql`
  query GetUser($id: ID!) {
    user(id: $id) {
      id
      name
      isFollowing @client # Local field
    }
  }
`;

function UserProfile({ userId }) {
  const { data } = useQuery(GET_USER, {
    variables: { id: userId }
  });

  return (
    <div>
      <p>{data.user.name}</p>
      <p>{data.user.isFollowing ? 'Following' : 'Not following'}</p>
    </div>
  );
}
